import {prepare,simulate,flow,SECTORS,COLORS,DEFAULT,COORDS} from './engine.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let raw,geo,model,run,base,quarter=0,view='overview',selected=null,mapMetric='gdp',mapZoom=1,playing=null,agentType='All',agentCountry='ALL',agentPage=0,sortKey='gdp',sortDir=-1,selectedAgent=null,sensitivity=null,scenarioParams={...DEFAULT,energy:25},saved=[];
let executionEvents=[],runSequence=0,runTimeMs=0,canvasMode='network',playDelay=700;
try{saved=JSON.parse(localStorage.getItem('atlas-scenarios')||'[]').filter(s=>s.name&&s.params).slice(0,30);}catch{}
const pct=(n,d=1)=>Number.isFinite(n)?n.toFixed(d)+'%':'—',sgn=(n,d=2)=>Number.isFinite(n)?(n>0?'+':'')+n.toFixed(d):'—',money=n=>Math.abs(n)>=1000?'$'+(n/1000).toFixed(2)+'T':'$'+n.toFixed(n<1?3:1)+'B',num=n=>new Intl.NumberFormat('en',{notation:'compact',maximumFractionDigits:1}).format(n),time=q=>q===0?'2023 · Baseline':`${2023+Math.ceil(q/4)} Q${(q-1)%4+1}`;
const frames=()=>run.frames[quarter],baseline=()=>base.frames[quarter];
const scope=f=>selected?f.states.find(c=>c.code===selected):f;
const impact=c=>{const b=baseline().states.find(v=>v.code===c.code);return (c.gdp/b.gdp-1)*100;};
const inputs=['fiscal','rate','tariff','energy','supply','carbon','climate','confidence'];
const presets={energy:{name:'Energy price shock',description:'A 50% increase in energy prices pushes up costs and feeds through supply chains.',params:{energy:50}},trade:{name:'Trade fragmentation',description:'A 20 pp tariff increase and 10% supply disruption stress connected producers.',params:{tariff:20,supply:10}},stimulus:{name:'Infrastructure stimulus',description:'A $100B injection flows into suppliers, incomes, profits, and taxes.',params:{fiscal:100,duration:4}},tightening:{name:'Monetary tightening',description:'A 2 pp rate increase dampens investment and household demand.',params:{rate:2}},climate:{name:'Climate stress',description:'A 3% climate damage shock with a 10% supply disruption.',params:{climate:3,supply:10}},transition:{name:'Carbon transition',description:'A $100/tonne carbon cost paired with $150B of public investment.',params:{carbon:100,fiscal:150}},confidence:{name:'Confidence collapse',description:'A 25-point sentiment decline feeds through consumption and credit risk.',params:{confidence:-25}},india:{name:'India capital experiment',description:'Inject $100 million into India and inspect its sectoral footprint.',params:{target:'IND',fiscal:.1,duration:1}}};
function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;setTimeout(()=>{const t=$('#toast');if(t)t.hidden=true;},3200);}
function getParams(){const p={...DEFAULT};inputs.forEach(k=>p[k]=+$('#'+k).value);['duration','horizon'].forEach(k=>p[k]=+$('#'+k).value);p.target=$('#target').value;return p;}
function setParams(p){p={...DEFAULT,...p};inputs.forEach(k=>{$('#'+k).value=p[k];$('#'+k+'Exact').value=p[k];});['target','duration','horizon'].forEach(k=>$('#'+k).value=String(p[k]));$('#fiscalExact').value=p.fiscal;updateOutputs();}
function updateOutputs(){const p=getParams();inputs.forEach(k=>$('#'+k+'Val').textContent=k==='fiscal'?money(p[k]):k==='rate'||k==='tariff'?sgn(p[k],k==='rate'?2:0)+' pp':k==='carbon'?'$'+p[k]+'/t':k==='confidence'?sgn(p[k],0)+' pts':sgn(p[k],k==='climate'?1:0)+'%');}
function dirty(){updateOutputs();$('#runStatus').textContent='INPUT MODIFIED';$$('.presets button').forEach(b=>b.classList.remove('active'));$('#runBtn').textContent='EXECUTE UPDATED VECTOR ↵';}
async function execute(p=getParams()){
 stop();runSequence++;appendLog('RUN',`EXECUTE target=${p.target} horizon=${p.horizon}q duration=${p.duration}q seed=${p.seed}`);$('#runBtn').disabled=true;$('#runStatus').textContent='SOLVING';await new Promise(r=>setTimeout(r,20));
 try{const started=performance.now();scenarioParams=p;base=simulate(model,{...DEFAULT,horizon:p.horizon,seed:p.seed});run=simulate(model,p,logFrame);runTimeMs=performance.now()-started;appendLog('DONE',`PAIRED RUN COMPLETE · ${p.horizon} ticks · ${runTimeMs.toFixed(1)} ms`);quarter=Math.min(quarter,p.horizon);if(quarter===0&&inputs.some(k=>p[k]!==0))quarter=1;sensitivity=null;$('#timeline').max=p.horizon;$('#timelineEnd').textContent=time(p.horizon);$('#runStatus').textContent='CONVERGED';render();toast('Scenario computed · '+p.horizon+' quarters');}catch(e){showError(e);}finally{$('#runBtn').disabled=false;$('#runBtn').innerHTML='EXECUTE SCENARIO <span>↵</span>';}
}
function stop(){if(playing){clearInterval(playing);appendLog('STEP','PLAYBACK PAUSED',quarter);}playing=null;$('#playBtn').textContent='▶';$('#playBtn').setAttribute('aria-label','Play simulation');}
function play(){if(playing){stop();return;}if(quarter===run.params.horizon)quarter=0;appendLog('STEP','PLAYBACK STARTED',quarter);$('#playBtn').textContent='Ⅱ';$('#playBtn').setAttribute('aria-label','Pause simulation');playing=setInterval(()=>{quarter++;if(quarter>=run.params.horizon)stop();render();appendLog('STEP',`DISPLAY ${time(quarter)} · precomputed state`,quarter);},playDelay);}
function showError(e){appendLog('ERROR',e.message);console.error(e);$('#errorBanner').textContent='Unable to finish this operation: '+e.message;$('#errorBanner').hidden=false;}
function kpi(label,value,delta,sub,bad=false){return `<div class="kpi"><div class="kpi-label">${label}<span>Δ</span></div><div class="kpi-value">${value}</div><div class="kpi-change ${bad?'negative':''}">${delta}</div><div class="kpi-sub">${sub}</div></div>`;}
function cards(){const f=scope(frames()),b=scope(baseline()),dg=(f.gdp/b.gdp-1)*100,inf=f.inflation-b.inflation,un=f.unemployment-b.unemployment;return `<div class="kpis">${kpi(selected?'Economy GDP':'World GDP',money(f.gdp),sgn(dg)+'% vs. baseline','Real output · 2023 USD',dg<0)}${kpi('Annualized growth',pct(f.growth),sgn(f.growth-b.growth)+' pp vs. baseline','Quarter-on-quarter, annualized',f.growth<b.growth)}${kpi('Consumer inflation',pct(f.inflation),sgn(inf)+' pp vs. baseline','Annual rate · GDP weighted',inf>0)}${kpi('Unemployment',pct(f.unemployment),sgn(un)+' pp vs. baseline','Labor force share · stylized',un>0)}</div>`;}
function countryList(){const term=$('#countrySearch').value.toLowerCase();$('#countryList').innerHTML=model.countries.filter(c=>c.code!=='ROW'&&(c.name.toLowerCase().includes(term)||c.code.toLowerCase().includes(term))).sort((a,b)=>b.gdp-a.gdp).slice(0,term?35:8).map(c=>`<button data-country="${c.code}" class="${c.code===selected?'selected':''}"><span class="flag-dot"></span>${esc(c.name)}<small>${c.code}</small></button>`).join('');}
function topScope(){return selected?`<div class="view-intro"><div><div class="eyebrow">ECONOMY FOCUS</div><h2>${esc(model.countries.find(c=>c.code===selected).name)}</h2><p>National indicators and trajectories. The map continues to show the connected global system.</p></div><button id="clearFocus">← Global view</button></div>`:'';}
function mapCard(network=false){return `<div class="card"><div class="card-head"><div><h3>${network?'The arteries of the world economy':'A connected economic landscape'}</h3><p>${network?'Synthetic intermediate-goods corridors · select any economy':'Select an economy to inspect its trajectory and exposure'}</p></div><div class="segmented" id="mapMetrics">${['gdp','impact','growth'].map(k=>`<button data-metric="${k}" class="${mapMetric===k?'active':''}">${k==='gdp'?'GDP':k==='impact'?'Shock impact':'Growth'}</button>`).join('')}</div></div><div class="map-wrap"><div class="map-toolbar"><button id="zoomOut" aria-label="Zoom out map">−</button><button id="zoomIn" aria-label="Zoom in map">＋</button><button id="zoomReset" aria-label="Reset map zoom">⌖</button><small>${network?'40 strongest modeled corridors':'35 economies + rest of world'}</small></div><svg id="worldMap" viewBox="0 0 1000 500" aria-label="Interactive map of modeled economies" role="img"></svg><div class="map-legend">${mapMetric==='gdp'?'Economic scale · GDP':mapMetric==='impact'?'Output change vs. baseline':'Annualized output growth'}<div class="gradient" style="${mapMetric!=='gdp'?'background:linear-gradient(90deg,#ff5252,#353e4b,#00e676)':''}"></div><div class="scale"><span>${mapMetric==='gdp'?'Lower':'Negative'}</span><span>${mapMetric==='gdp'?'Higher':'Positive'}</span></div></div><div class="map-note">Geography: Natural Earth<br>Trade links: assumed gravity weights</div></div><div class="map-bottom"><span><span class="live-dot"></span><strong>${time(quarter)}</strong> · ${run.params.target==='ALL'?'Global shock':run.params.target+' targeted shock'}</span><span>${frames().rationing<.999?'Capacity closure: '+(frames().rationing*100).toFixed(1)+'% of requested demand':'Scroll time to watch the spillovers <strong>→</strong>'}</span></div></div>`;}
function project([lon,lat]){return [((lon+180)/360)*1000,((83-lat)/150)*500];}
function pathGeo(g){const poly=g.type==='Polygon'?[g.coordinates]:g.type==='MultiPolygon'?g.coordinates:[];return poly.map(p=>p.map(r=>r.map((coord,i)=>{const [x,y]=project(coord);return `${i?'L':'M'}${x.toFixed(1)},${y.toFixed(1)}`;}).join('')+'Z').join('')).join('');}
function colorCountry(code){const c=frames().states.find(c=>c.code===code);if(!c)return '#1c222d';if(mapMetric==='gdp'){const s=Math.log(1+c.gdp)/Math.log(1+30000);return `hsl(213 ${25+s*22}% ${18+s*37}%)`; }const v=mapMetric==='impact'?impact(c):c.growth;if(Math.abs(v)<.01)return '#353e4b';return v<0?`hsl(0 65% ${Math.min(60,29+Math.abs(v)*3)}%)`:`hsl(150 70% ${Math.min(53,24+Math.abs(v)*2)}%)`;}
function drawMap(network=view==='trade'||(view==='overview'&&canvasMode==='network')){
 const map=$('#worldMap');if(!map)return;const fs=frames().states;let inner='';for(let lat=-60;lat<=60;lat+=30){const y=project([0,lat])[1];inner+=`<path class="grid-line" d="M0 ${y}H1000"/>`;}for(let lon=-180;lon<=180;lon+=30){const x=project([lon,0])[0];inner+=`<path class="grid-line" d="M${x} 0V500"/>`;}
 inner+=geo.features.filter(f=>f.properties.code!=='ATA').map(f=>{const code=f.properties.code,modeled=model.countries.some(c=>c.code===code);return `<path d="${pathGeo(f.geometry)}" class="country-shape ${code===selected?'selected':''}" fill="${colorCountry(code)}" data-map-country="${esc(code)}" ${modeled?`tabindex="0" role="button" aria-label="Inspect ${esc(f.properties.name)}"`:''}/>`;}).join('');
 const links=model.links.filter(l=>!selected||model.countries[l.from].code===selected||model.countries[l.to].code===selected).slice(0,network?40:18);for(const l of links){const a=model.countries[l.from],b=model.countries[l.to];if(a.code==='ROW'||b.code==='ROW')continue;const [ax,ay]=project(a.coords),[bx,by]=project(b.coords);inner+=`<path class="trade-line" d="M${ax},${ay}Q${(ax+bx)/2},${Math.min(ay,by)-Math.min(80,Math.abs(ax-bx)/5)} ${bx},${by}" stroke-width="${network?Math.max(.7,Math.sqrt(l.value)/7):.9}"/>`;}
 const labels=['USA','CHN','IND','DEU','BRA','AUS','RUS','ZAF'];fs.forEach(c=>{if(c.code==='ROW')return;const[x,y]=project(c.coords);inner+=`<circle class="country-point" cx="${x}" cy="${y}" r="${network?Math.max(3,Math.log(c.gdp)*1.1):3}" data-map-country="${c.code}" tabindex="0" role="button" aria-label="Inspect ${esc(c.name)}"/>`;if(labels.includes(c.code))inner+=`<text x="${x}" y="${y-11}" class="country-label">${c.code}</text>`;});
 map.innerHTML=`<g transform="translate(${500*(1-mapZoom)} ${250*(1-mapZoom)}) scale(${mapZoom})">${inner}</g>`;
 map.querySelectorAll('[data-map-country]').forEach(el=>{
  const code=el.dataset.mapCountry,c=fs.find(c=>c.code===code);el.addEventListener('pointermove',e=>{if(!c)return;$('#tooltip').innerHTML=`<strong>${esc(c.name)}</strong><br>Output ${money(c.gdp)}<br>Growth ${pct(c.growth)} · inflation ${pct(c.inflation)}<br>Shock impact <span class="${impact(c)<0?'negative':'positive'}">${sgn(impact(c))}%</span><br><small>Click to inspect economy</small>`;$('#tooltip').hidden=false;$('#tooltip').style.left=Math.min(e.clientX+14,innerWidth-210)+'px';$('#tooltip').style.top=Math.min(e.clientY+14,innerHeight-170)+'px';});el.addEventListener('pointerleave',()=>$('#tooltip').hidden=true);el.addEventListener('click',()=>{if(c)openCountry(code);else toast('This economy is included in the rest-of-world aggregate.');});el.addEventListener('keydown',e=>{if(c&&(e.key==='Enter'||e.key===' ')){e.preventDefault();openCountry(code);}});
 });
}
function lineChart(series,{height=180,yformat=pct,zero=false}={}){
 const w=500,h=height,pl=47,pr=14,pt=12,pb=27,all=series.flatMap(s=>s.values);let min=Math.min(...all),max=Math.max(...all);if(zero){min=Math.min(min,0);max=Math.max(max,0);}const pad=Math.max(.1,(max-min)*.13);min-=pad;max+=pad;const px=i=>pl+i/(series[0].values.length-1)*(w-pl-pr),py=v=>pt+(max-v)/(max-min)*(h-pt-pb);let grid='';
 for(let i=0;i<=3;i++){let v=min+(max-min)*i/3,y=py(v);grid+=`<path class="chart-grid" d="M${pl} ${y}H${w-pr}"/><text class="chart-axis" x="${pl-7}" y="${y+3}" text-anchor="end">${esc(yformat(v))}</text>`;}
 const len=series[0].values.length;for(let i=0;i<=4;i++){const idx=Math.round((len-1)*i/4);grid+=`<text class="chart-axis" x="${px(idx)}" y="${h-7}" text-anchor="middle">${idx===0?'2023':'Y'+Math.ceil(idx/4)}</text>`;}
 let paths=series.map(s=>{const d=s.values.map((v,i)=>`${i?'L':'M'}${px(i)},${py(v)}`).join('');return `<path d="${d}" fill="none" stroke="${s.color}" stroke-width="2" ${s.dashed?'stroke-dasharray="4 4"':''}/>`;}).join('');
 const mx=px(quarter);paths+=`<path d="M${mx} ${pt}V${h-pb}" stroke="#00e676" stroke-width="1" stroke-dasharray="2 3" opacity=".5"/>`;series.forEach(s=>{const v=s.values[quarter];if(v!=null)paths+=`<circle cx="${mx}" cy="${py(v)}" r="3" fill="${s.color}"/>`;});
 return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(series.map(s=>s.name).join(' versus '))} trajectory">${grid}${paths}</svg>`;
}
function trajectory(metric='gdp'){const scale=metric==='risk'?100:1,b=base.frames.map(f=>scope(f)[metric]*scale),r=run.frames.map(f=>scope(f)[metric]*scale);return lineChart([{name:'No-shock baseline',values:b,color:'#667387',dashed:true},{name:'Scenario',values:r,color:'#00e676'}],{yformat:metric==='gdp'?v=>money(v):pct});}
function sectorsBars(){const f=frames();const vals=selected?scope(f).sectors:SECTORS.map((s,i)=>f.states.reduce((a,c)=>a+c.sectors[i],0)),sum=vals.reduce((a,b)=>a+b,0);return `<div class="sector-bars">${vals.map((v,i)=>`<div class="sector-row"><span>${SECTORS[i]}</span><div class="bar-track"><div class="bar-fill" style="width:${v/sum*100}%;background:${COLORS[i]}"></div></div><strong>${pct(v/sum*100,0)}</strong></div>`).join('')}</div>`;}
function countryTable(limit=10){const rows=[...frames().states].sort((a,b)=>sortDir*((sortKey==='impact'?impact(a):a[sortKey])-(sortKey==='impact'?impact(b):b[sortKey]))).slice(0,limit);return `<div class="table-wrap"><table class="table"><thead><tr><th>Economy</th>${[['gdp','GDP ↕'],['growth','Growth ↕'],['inflation','Inflation ↕'],['impact','Shock impact ↕']].map(([k,t])=>`<th class="num"><button class="sort" data-sort="${k}">${t}</button></th>`).join('')}</tr></thead><tbody>${rows.map(c=>`<tr><td><button data-country="${c.code}"><span class="code">${c.code}</span>${esc(c.name)}</button></td><td class="num">${money(c.gdp)}</td><td class="num">${pct(c.growth)}</td><td class="num">${pct(c.inflation)}</td><td class="num ${impact(c)<-.001?'negative':'positive'}">${sgn(impact(c))}%</td></tr>`).join('')}</tbody></table></div>`;}
function phaseChart(){const vals=run.frames.map(f=>({x:scope(f).growth,y:scope(f).inflation})),w=470,h=230,px=48,pb=34,pt=14,xs=vals.map(v=>v.x),ys=vals.map(v=>v.y),xmin=Math.min(...xs)-.8,xmax=Math.max(...xs)+.8,ymin=Math.min(...ys)-.4,ymax=Math.max(...ys)+.4,x=v=>px+(v-xmin)/(xmax-xmin)*(w-px-18),y=v=>pt+(ymax-v)/(ymax-ymin)*(h-pt-pb);let grid='';for(let i=0;i<4;i++){const xx=xmin+(xmax-xmin)*i/3,yy=ymin+(ymax-ymin)*i/3;grid+=`<path class="chart-grid" d="M${x(xx)} ${pt}V${h-pb}M${px} ${y(yy)}H${w-18}"/><text class="chart-axis" x="${x(xx)}" y="${h-pb+14}" text-anchor="middle">${xx.toFixed(1)}</text><text class="chart-axis" x="${px-9}" y="${y(yy)+3}" text-anchor="end">${yy.toFixed(1)}</text>`;}
 return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Inflation against annualized GDP growth through time">${grid}<path d="${vals.map((v,i)=>`${i?'L':'M'}${x(v.x)},${y(v.y)}`).join('')}" fill="none" stroke="#00e676" stroke-width="1.8"/>${vals.map((v,i)=>`<circle cx="${x(v.x)}" cy="${y(v.y)}" r="${i===quarter?5:2}" fill="${i===quarter?'#ffffff':'#468772'}"/>`).join('')}<text class="chart-axis" x="${w/2}" y="${h-2}" text-anchor="middle">ANNUALIZED GDP GROWTH (%)</text><text class="chart-axis" transform="translate(10 ${h/2}) rotate(-90)" text-anchor="middle">INFLATION (%)</text></svg>`;
}
function overview(){return topScope()+simulationCanvas()+`<div class="lower-grid"><div class="card"><div class="card-head"><div><h3>Output trajectory</h3><p>A paired run with the same initial conditions</p></div><span class="badge">${run.params.horizon/4}Y DYNAMIC</span></div><div class="chart-body"><div class="chart-legend"><span>Scenario</span><span class="baseline">Baseline</span></div>${trajectory()}</div></div><div class="card"><div class="card-head"><div><h3>Sector composition</h3><p>Share of modeled value added</p></div><span class="mini-icon">▥</span></div>${sectorsBars()}</div></div><div class="card"><div class="card-head"><div><h3>Economies at a glance</h3><p>Click a column to sort. Select a country to look closer.</p></div><button id="showAll" class="quiet">All economies ↗</button></div>${countryTable()}</div>`;}
function trade(){const links=model.links.filter(l=>!selected||model.countries[l.from].code===selected||model.countries[l.to].code===selected).slice(0,25);return topScope()+`<div class="stat-strip"><div><strong>${model.links.length}</strong><span>DIRECTED MODEL CORRIDORS</span></div><div><strong>${money(frames().trade)}</strong><span>ANNUALIZED INTERMEDIATE EXPORTS</span></div><div><strong>${money(model.links.reduce((s,l)=>s+l.value,0))}</strong><span>BASELINE CROSS-BORDER INPUTS</span></div></div>`+mapCard(true)+`<div class="card"><div class="card-head"><div><h3>Corridor exposure</h3><p>Supplier → consuming economy · assumed gravity network, not measured bilateral trade</p></div><span class="badge">SYNTHETIC LINKS</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Supplier</th><th>Buyer</th><th class="num">Baseline input flow</th><th class="num">Supplier output impact</th></tr></thead><tbody>${links.map(l=>{const a=frames().states[l.from],b=model.countries[l.to];return `<tr><td><button data-country="${a.code}">${esc(a.name)}</button></td><td><button data-country="${b.code}">${esc(b.name)}</button></td><td class="num">${money(l.value)}</td><td class="num ${impact(a)<0?'negative':'positive'}">${sgn(impact(a))}%</td></tr>`;}).join('')}</tbody></table></div></div><div class="card"><div class="card-head"><h3>Every modeled economy</h3></div>${countryTable(36)}</div>`;}
function sankey(){const amount=run.params.fiscal;if(amount<=0)return `<div class="empty-state">Choose a capital injection in the scenario builder to trace spending through the economy.<br><button id="tryCapital" class="quiet" style="margin-top:15px">Explore a $100M India injection →</button></div>`;const fl=flow(model,run.params),w=740,h=310,alloc=[.08,.15,.22,.30,.15,.10],unit=190/amount,ys=SECTORS.map((_,i)=>44+i*38),ends=[50,110,170,230],labels=['Wages','Profits','Taxes','Intermediate inputs'],keys=['wages','profits','tax','inputs'],tots=keys.map(k=>fl.dest.reduce((s,d)=>s+d[k],0));let links='',nodes='';
 SECTORS.forEach((s,i)=>{const sw=Math.max(3,amount*alloc[i]*unit);links+=`<path d="M110 150C185 150 205 ${ys[i]+8} 285 ${ys[i]+8}" fill="none" stroke="${COLORS[i]}" stroke-opacity=".3" stroke-width="${sw}"/>`;keys.forEach((k,j)=>{const v=fl.dest[i][k],th=Math.max(1,v/fl.totalGross*145);links+=`<path d="M310 ${ys[i]+8}C420 ${ys[i]+8} 430 ${ends[j]} 585 ${ends[j]}" fill="none" stroke="${COLORS[i]}" stroke-opacity=".28" stroke-width="${th}"/>`;});nodes+=`<rect x="285" y="${ys[i]}" width="8" height="18" rx="2" fill="${COLORS[i]}"/><text x="306" y="${ys[i]+6}" fill="#cbd4e2" font-size="10">${s}</text><text x="306" y="${ys[i]+19}" fill="#8796ab" font-size="8">${money(fl.sectors[i])} gross</text>`;});
 keys.forEach((k,j)=>nodes+=`<rect x="585" y="${ends[j]-11}" width="8" height="23" rx="2" fill="${j===3?'#768eae':'#00e676'}"/><text x="605" y="${ends[j]-1}" fill="#cbd4e2" font-size="11">${labels[j]}</text><text x="605" y="${ends[j]+13}" fill="#8796ab" font-size="9">${money(tots[j])}</text>`);
 return `<svg class="flow-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="Capital injection flows to sectors, wages, profits, taxes and intermediate inputs">${links}<rect x="103" y="115" width="8" height="70" rx="3" fill="#00e676"/><text x="13" y="137" fill="#00e676" font-size="17">${money(amount)}</text><text x="13" y="156" fill="#8796ab" font-size="10">Budget injection</text><text x="13" y="172" fill="#8796ab" font-size="9">${run.params.target==='ALL'?'GDP-weighted allocation':run.params.target}</text>${nodes}</svg><div class="small-note">Budget → allocation by sector; sector nodes show total direct and indirect gross output. Wages + profits + taxes = injected final demand. Intermediate inputs are repeated production flows, not extra GDP. Flow widths within each stage are scaled independently for legibility.</div>`;
}
function sectorsView(){const f=frames(),b=baseline(),vals=SECTORS.map((s,i)=>({name:s,value:(selected?[scope(f)]:f.states).reduce((a,c)=>a+c.sectors[i],0),base:(selected?[scope(b)]:b.states).reduce((a,c)=>a+c.sectors[i],0)}));return topScope()+`<div class="card"><div class="card-head"><div><h3>Follow the capital</h3><p>Leontief multiplier decomposition of your budget injection</p></div><span class="badge">FLOW OF FUNDS</span></div>${sankey()}</div><div class="card"><div class="card-head"><div><h3>Sector balance sheet</h3><p>Value added in baseline-year USD</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Sector</th><th class="num">No-shock baseline</th><th class="num">Scenario output</th><th class="num">Output change</th></tr></thead><tbody>${vals.map((v,i)=>`<tr><td><span style="color:${COLORS[i]}">●</span> ${v.name}</td><td class="num">${money(v.base)}</td><td class="num">${money(v.value)}</td><td class="num ${v.value<v.base?'negative':'positive'}">${sgn((v.value/v.base-1)*100)}%</td></tr>`).join('')}</tbody></table></div></div><div class="card"><div class="card-head"><div><h3>Input-output coefficient matrix</h3><p>Mean coefficient across countries · supplier rows, purchasing columns</p></div><span class="badge">6 × 6 BLOCK</span></div>${matrix()}<div class="small-note">Synthetic technical coefficients are balanced for positive final demand and calibrated to the observed GDP baseline. The complete 216 × 216 matrix includes domestic and imported inputs.</div></div>`;}
function matrix(){let html='<div class="matrix"><div class="matrix-label">INPUT / OUTPUT</div>'+SECTORS.map(s=>`<div class="matrix-label">${s.slice(0,8)}</div>`).join('');for(let i=0;i<6;i++){html+=`<div class="matrix-label">${SECTORS[i]}</div>`;for(let j=0;j<6;j++){let a=0;for(let c=0;c<model.countries.length;c++)for(let supplier=0;supplier<model.countries.length;supplier++)a+=model.A[supplier*6+i][c*6+j];a/=model.countries.length;html+=`<div style="background:rgba(88,151,216,${.09+a*2})">${a.toFixed(3)}</div>`;}}return html+'</div>';}
function agentView(){const a=run.agents.filter(a=>(agentType==='All'||a.type===agentType)&&(agentCountry==='ALL'||model.countries[a.country].code===agentCountry)),page=a.slice(agentPage*40,agentPage*40+40);return `<div class="view-intro"><div><div class="eyebrow">BOTTOM-UP MICROFOUNDATIONS</div><h2>${num(run.agents.length)} agents / bounded-rational rules</h2><p>Households adjust consumption and savings. Firms react to costs and credit. Banks respond to borrower stress. Their aggregate decisions feed demand in the next quarter.</p></div><span class="badge">SEED ${run.seed}</span></div><div class="stat-strip"><div><strong>${model.countries.length*36}</strong><span>HOUSEHOLD COHORTS</span></div><div><strong>${model.countries.length*24}</strong><span>SECTOR FIRMS</span></div><div><strong>${model.countries.length*4}</strong><span>COMMERCIAL BANKS</span></div></div><div class="card"><div class="card-head"><div><h3>Population observatory</h3><p>One square = one agent · ${time(run.params.horizon)} endpoint states</p></div><span class="badge">${a.length} AGENTS</span></div><div class="agent-controls"><select id="agentType" aria-label="Agent type">${['All','Household','Firm','Bank'].map(t=>`<option ${t===agentType?'selected':''}>${t}</option>`).join('')}</select><select id="agentCountry" aria-label="Agent economy"><option value="ALL">All economies</option>${model.countries.map(c=>`<option value="${c.code}" ${c.code===agentCountry?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="agent-dot-grid">${a.map(v=>`<button class="agent-dot" data-agent="${v.id}" title="${v.id} · ${v.type}" aria-label="Inspect ${v.id}" style="background:${v.type==='Household'?'#94b874':v.type==='Firm'?'#65b4b2':'#b9a478'};opacity:${1-v.stress}"></button>`).join('')}</div>${selectedAgent?agentDetail(selectedAgent):''}<div class="small-note">Agent values show the end of the computed horizon. Timeline controls affect macro charts; agents are representative cohorts, not real people or firms.</div></div><div class="card"><div class="card-head"><div><h3>Agent ledger</h3><p>Inspect a row to see its behavioral rule</p></div><div><button id="prevAgents" aria-label="Previous agent page">←</button> <span class="muted">${agentPage+1}/${Math.max(1,Math.ceil(a.length/40))}</span> <button id="nextAgents" aria-label="Next agent page">→</button></div></div><div class="table-wrap"><table class="table"><thead><tr><th>ID / cohort</th><th>Economy</th><th>Type</th><th class="num">Demand index</th><th class="num">Credit / savings</th></tr></thead><tbody>${page.map(v=>`<tr><td><button data-agent="${v.id}">${v.id}</button></td><td>${model.countries[v.country].code}</td><td>${v.type}</td><td class="num">${v.demand.toFixed(3)}</td><td class="num">${v.type==='Household'?v.savings.toFixed(2)+' savings index':v.type==='Firm'?v.credit.toFixed(3)+' credit':pct(v.risk*100)+' risk'}</td></tr>`).join('')}</tbody></table></div></div>`;}
function agentDetail(id){const a=run.agents.find(a=>a.id===id);if(!a)return '';return `<div class="agent-detail"><strong>${a.id} · ${a.type}</strong><br>${a.type==='Household'?`Consumption propensity: ${a.mpc.toFixed(3)} · savings index: ${a.savings.toFixed(3)}<br>Rule: consume a fraction of income; reduce demand when inflation, unemployment or borrowing costs rise.`:a.type==='Firm'?`Sector: ${SECTORS[a.sector]} · inventory index: ${a.inventory.toFixed(3)} · price index: ${a.price.toFixed(3)} · credit access: ${a.credit.toFixed(3)}<br>Rule: adjust prices to input costs and demand to output gaps and available credit.`:`Leverage: ${a.leverage.toFixed(2)}× · borrower stress: ${pct(a.stress*100)} · risk proxy: ${pct(a.risk*100)}<br>Rule: tighten the risk proxy when output falls, unemployment rises, or borrowing costs increase.`}</div>`;}
function libraryView(){return `<div class="view-intro"><div><div class="eyebrow">EXPERIMENT, THEN COMPARE</div><h2>Scenario registry</h2><p>Start from a preset or save your own combination of shocks. All scenarios use the same baseline and seed for a fair comparison.</p></div><button id="saveHere" class="quiet">⊕ Save current</button></div><div class="scenario-cards">${Object.entries(presets).map(([k,s],i)=>`<div class="scenario-card"><div class="scenario-icon">${['↗','⇄','＋','%','☼','◈','↘','₹'][i]}</div><h3>${s.name}</h3><p>${s.description}</p><button data-preset="${k}">Load & run scenario →</button></div>`).join('')}</div><div class="card"><div class="card-head"><div><h3>Saved experiments</h3><p>Stored on this device · export JSON to move a scenario</p></div><button id="importScenario" class="quiet">↑ Import JSON</button><input id="importFile" type="file" accept="application/json,.json" hidden></div>${saved.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Name</th><th>Target</th><th>Horizon</th><th>Actions</th></tr></thead><tbody>${saved.map((s,i)=>`<tr><td>${esc(s.name)}</td><td>${esc(s.params.target)}</td><td>${s.params.horizon/4} years</td><td><button data-load="${i}">Run</button> · <button data-json="${i}">Export</button> · <button data-delete="${i}" class="negative">Delete</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">Your saved scenarios will appear here. Run a scenario, then choose “Save scenario”.</div>'}</div><div class="card"><div class="card-head"><div><h3>Compare against a saved scenario</h3><p>Current run and selected run share initial conditions</p></div></div><div class="compare-control"><select id="compareSelect" aria-label="Comparison scenario"><option value="">Select a saved scenario</option>${saved.map((s,i)=>`<option value="${i}">${esc(s.name)}</option>`).join('')}</select><button id="compareBtn" class="quiet">Compare</button></div><div id="comparison" class="chart-body"><div class="empty-state">Save two experiments to compare their world output paths.</div></div></div>`;}
function modelView(){const f=frames(),m=model;return `<div class="view-intro"><div><div class="eyebrow">TRANSPARENT BY DESIGN</div><h2>Model specification & source provenance</h2><p>Observed macro data anchor the starting state. Assumed coefficients generate the dynamics. The distinction is visible and exportable.</p></div><span class="badge">RESEARCH SANDBOX</span></div><div class="stat-strip"><div><strong>${m.N} × ${m.N}</strong><span>GLOBAL INPUT-OUTPUT MATRIX</span></div><div><strong>${f.residual.toExponential(1)}</strong><span>RELATIVE SOLVER RESIDUAL</span></div><div><strong>${f.accountingError.toExponential(1)}</strong><span>GLOBAL ACCOUNTING ERROR</span></div></div><div class="card"><div class="card-head"><h3>The five layers</h3><span class="badge">IMPLEMENTED</span></div><div class="method-body">${[
 ['Data & economic state','World Bank GDP, growth, population, inflation, unemployment, trade ratios and sector value added for 2023. 35 economies plus a residual rest-of-world region. Read-only baseline JSON and an in-memory country-sector graph.'],
 ['Heterogeneous agent mesh','36 household cohorts, 24 firms and 4 commercial banks per region. A reproducible seed assigns propensities, inventories and leverage. Agent responses alter final demand and risk. Monetary response is an aggregate policy rule, not an autonomous central-bank agent.'],
 ['Input-output & macro core','A 216-node Leontief system solved to tolerance, coupled to stylized quarterly inflation, unemployment, rate, FX and credit dynamics. Positive final demand is calibrated to each country’s baseline GDP. This is an IO + agent + macro hybrid, not a full optimizing CGE solver.'],
 ['Shock orchestrator','Country-targeted or GDP-weighted global fiscal spending, rates, tariffs, energy, supply, carbon, climate and sentiment. One-off fiscal spending occurs in quarter one; other shocks persist for the selected duration. Paired baseline runs isolate scenario effects.'],
 ['Spatial & temporal interface','Interactive geography, synthetic trade corridors, capital-flow decomposition, phase space, country detail, endpoint agent inspection, playback, saved scenarios and CSV/JSON exports. All simulation runs in your browser.']].map(([t,d],i)=>`<div class="tier"><div class="tier-num">${i+1}</div><div><strong>${t}</strong><p>${d}</p></div></div>`).join('')}</div></div><div class="two-grid"><div class="card"><div class="card-head"><h3>Observed data</h3><span class="badge">WDI 2023</span></div><div class="method-body"><p>Downloaded ${esc(raw.retrievedAt)} from the World Bank Indicators API. Common-year observations are used throughout. Rest-of-world GDP and population are residuals of world totals; its other parameters use world aggregates or explicit fallbacks.</p><p><a href="https://datahelpdesk.worldbank.org/knowledgebase/articles/889392" target="_blank" rel="noopener">World Bank API documentation ↗</a><br><a href="https://data.worldbank.org/indicator/NY.GDP.MKTP.CD" target="_blank" rel="noopener">GDP source & metadata ↗</a><br><a href="https://www.oecd.org/en/data/datasets/inter-country-input-output-tables.html" target="_blank" rel="noopener">OECD ICIO reference ↗</a> (methodological reference; its matrices are not loaded)</p><p>Missing macro observations filled with documented fallback values: ${m.missing.length}. ${m.missing.length?esc(m.missing.join(', ')):'All selected core series are available.'}</p><button id="refreshData" class="quiet">↻ Refresh 2023 WDI observations</button> <button id="downloadData" class="quiet">↓ Baseline JSON</button><p id="refreshStatus" class="muted">Refresh needs access to the public World Bank API; failures preserve the current data.</p></div></div><div class="card"><div class="card-head"><h3>Assumed structure</h3><span class="badge">NOT ESTIMATED</span></div><div class="method-body"><p>Trade shares use GDP and geographic distance. Sector technical coefficients are synthetic. Energy and infrastructure split non-manufacturing industry 50/50; technology receives 16% of measured services. These are modeling allocations, not observed subsectors.</p><p>Initial policy rate = 0.65 × inflation + 1.5 pp (floor 1%). Public debt starts at an assumed 60% of GDP. Banking risk, leverage, sentiment, FX response and all behavioral elasticities are illustrative, not empirically fitted.</p><p>Trade visualization shows intermediate inputs only; measured WDI export/import ratios are available in country details. Map: Natural Earth public-domain geography, distributed by <a href="https://github.com/datasets/geo-countries" target="_blank" rel="noopener">geo-countries ↗</a>.</p></div></div></div><div class="card"><div class="card-head"><h3>Equations & closure</h3></div><div class="method-body"><div class="equation">x = A x + d &nbsp; → &nbsp; x = (I − A)⁻¹ d<br>GDP = Σⱼ (1 − Σᵢ Aᵢⱼ) xⱼ = Σⱼ dⱼ</div><p>Here x is annualized gross output, A contains input requirements per unit output, and d is final demand. The fixed-point solver stops when the maximum relative update is below 10⁻¹⁰, with 140 iterations maximum. Columns sum to less than one, so the input-output iteration converges.</p><div class="equation">trendᶜ(q) = (1 + annual growthᶜ / 100)^(q/4)<br>π(q) = 0.70 π(q−1) + 0.30 π₀ + 0.14 output gap + cost shocks<br>u(q) = u₀ − 0.32 output gap<br>i(q) = i₀ + rate shock + 0.35(π(q) − π₀)</div><p>Output gap is a percentage deviation from each country’s no-shock growth trend. Fiscal spending is converted into annualized quarterly demand (budget × 4); the capital-flow diagram uses the actual one-off budget. All USD amounts after baseline are real-output proxies in baseline-year dollars, not nominal USD forecasts.</p><p>Supply constraints use a conservative global final-demand rationing factor when any sector exceeds capacity, followed by a new IO solve. This keeps accounting consistent but overstates synchronized bottleneck transmission. It is not a market-clearing or sector-specific rationing algorithm.</p><p>Growth is quarter-on-quarter annualized and can jump sharply at shock onset or removal. Global inflation and unemployment are GDP-weighted composites, not official aggregate indicators. No uncertainty band is a statistical confidence interval.</p><p>No learned AI agents, observed bilateral matrix, nominal national-account closure, sovereign bond market, endogenous demographics, climate physics, model estimation or real-time news alignment is implemented. These need new data, validation and additional models.</p></div><div class="sensitivity-box"><button id="sensitivityBtn">Test response sensitivity →</button><span id="sensitivityResult">Re-run at 0.7×, 1.0× and 1.3× assumed shock elasticities.</span></div></div><div class="card"><div class="card-head"><div><h3>Input-output accounting ledger</h3><p>${time(quarter)} · annualized USD billions</p></div><span class="badge">CHECKED</span></div><div class="table-wrap"><table class="table"><tbody><tr><td>Gross output (includes repeated intermediate production)</td><td class="num">${money(f.grossOutput)}</td></tr><tr><td>Intermediate inputs</td><td class="num">${money(f.grossOutput-f.ioValueAdded)}</td></tr><tr><td>Value added / GDP</td><td class="num">${money(f.ioValueAdded)}</td></tr><tr><td>Final demand</td><td class="num">${money(f.finalDemand)}</td></tr><tr><td>Relative identity error</td><td class="num">${f.accountingError.toExponential(3)}</td></tr></tbody></table></div></div>`;}
const titles={overview:['Global overview','Global state / network','Synthetic trade connectivity and sector output'],trade:['Trade network','Bilateral input corridors','Assumed gravity weights / directed supply relationships'],sectors:['Sector economy','Sector ledger / capital flows','Input-output multiplier decomposition'],agents:['Agent observatory','Agent state observatory','Household / firm / bank endpoint state'],scenarios:['Scenario library','Scenario registry / comparisons','Reproducible paired experiments'],model:['Model & data','Model specification / source ledger','Equations, observations and numerical closure']};
function render(){if(!run)return;const t=titles[view];$('#breadcrumb').textContent=t[0];$('#pageTitle').textContent=t[1];$('#pageSubtitle').textContent=t[2];$('#eyebrow').textContent='ATLAS / '+view.toUpperCase();$('#viewContent').innerHTML=({overview,trade,sectors:sectorsView,agents:agentView,scenarios:libraryView,model:modelView})[view]();$$('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#timeLabel').textContent=time(quarter);$('#timeline').value=quarter;$('#solverStatus').textContent='IO residual '+frames().residual.toExponential(1);countryList();bindView();drawMap();renderTelemetry();if($('#sensitivityResult')&&sensitivity)$('#sensitivityResult').textContent=sensitivity;}
function changeView(v){view=v;render();$('.workspace-scroll').scrollTop=0;appendLog('VIEW',v.toUpperCase()+' WORKSPACE');history.replaceState(null,'','#'+v);}
function bindView(){
 $$('[data-canvas]').forEach(b=>b.onclick=()=>{canvasMode=b.dataset.canvas;render();appendLog('VIEW','CANVAS '+canvasMode.toUpperCase());});
 $$('[data-country]').forEach(b=>b.onclick=()=>openCountry(b.dataset.country));$$('[data-sort]').forEach(b=>b.onclick=()=>{sortDir=sortKey===b.dataset.sort?-sortDir:-1;sortKey=b.dataset.sort;render();});$$('[data-metric]').forEach(b=>b.onclick=()=>{mapMetric=b.dataset.metric;render();});$$('[data-preset]').forEach(b=>b.onclick=()=>loadPreset(b.dataset.preset));
 if($('#clearFocus'))$('#clearFocus').onclick=()=>{selected=null;render();};if($('#showAll'))$('#showAll').onclick=()=>changeView('trade');if($('#zoomIn'))$('#zoomIn').onclick=()=>{mapZoom=Math.min(3,mapZoom+.3);drawMap();};if($('#zoomOut'))$('#zoomOut').onclick=()=>{mapZoom=Math.max(1,mapZoom-.3);drawMap();};if($('#zoomReset'))$('#zoomReset').onclick=()=>{mapZoom=1;drawMap();};if($('#tryCapital'))$('#tryCapital').onclick=()=>loadPreset('india');
 if($('#agentType'))$('#agentType').onchange=e=>{agentType=e.target.value;agentPage=0;render();};if($('#agentCountry'))$('#agentCountry').onchange=e=>{agentCountry=e.target.value;agentPage=0;render();};$$('[data-agent]').forEach(b=>b.onclick=()=>{selectedAgent=b.dataset.agent;render();});if($('#prevAgents'))$('#prevAgents').onclick=()=>{agentPage=Math.max(0,agentPage-1);render();};if($('#nextAgents'))$('#nextAgents').onclick=()=>{const count=run.agents.filter(a=>(agentType==='All'||a.type===agentType)&&(agentCountry==='ALL'||model.countries[a.country].code===agentCountry)).length;agentPage=Math.min(Math.ceil(count/40)-1,agentPage+1);render();};
 if($('#saveHere'))$('#saveHere').onclick=saveOpen;$$('[data-load]').forEach(b=>b.onclick=()=>{setParams(saved[+b.dataset.load].params);execute();});$$('[data-json]').forEach(b=>b.onclick=()=>download('atlas-scenario.json',JSON.stringify(saved[+b.dataset.json],null,2),'application/json'));$$('[data-delete]').forEach(b=>b.onclick=()=>{saved.splice(+b.dataset.delete,1);persist();render();toast('Scenario removed');});
 if($('#importScenario'))$('#importScenario').onclick=()=>$('#importFile').click();if($('#importFile'))$('#importFile').onchange=importScenario;
 if($('#compareBtn'))$('#compareBtn').onclick=()=>{const i=$('#compareSelect').value;if(i===''){toast('Select a saved scenario first.');return;}const s=saved[+i],comp=simulate(model,{...s.params,horizon:run.params.horizon});$('#comparison').innerHTML=`<div class="chart-legend"><span>Current scenario</span><span class="secondary">${esc(s.name)}</span></div>`+lineChart([{name:'Current scenario',values:run.frames.map(f=>f.gdp),color:'#00e676'},{name:s.name,values:comp.frames.map(f=>f.gdp),color:'#70a7e6'}],{height:210,yformat:money})+`<div class="small-note">Endpoint difference: ${money(run.frames.at(-1).gdp-comp.frames.at(-1).gdp)} of annualized output. Compared at the current run’s horizon.</div>`;};
 if($('#downloadData'))$('#downloadData').onclick=()=>download('atlas-wdi-2023-baseline.json',JSON.stringify(raw,null,2),'application/json');if($('#refreshData'))$('#refreshData').onclick=refreshData;if($('#sensitivityBtn'))$('#sensitivityBtn').onclick=async()=>{const b=$('#sensitivityBtn');b.disabled=true;await new Promise(r=>setTimeout(r,20));const vals=[.7,1,1.3].map(e=>simulate(model,{...run.params,elasticity:e}).frames.at(-1).gdp),ref=base.frames.at(-1).gdp;sensitivity=`Endpoint world output impact ranges from ${sgn((Math.min(...vals)/ref-1)*100)}% to ${sgn((Math.max(...vals)/ref-1)*100)}%. A parameter sensitivity range, not a confidence interval.`;$('#sensitivityResult').textContent=sensitivity;b.disabled=false;};
}
function openCountry(code){stop();const c=frames().states.find(c=>c.code===code),b=baseline().states.find(c=>c.code===code),obs=model.countries.find(c=>c.code===code);if(!c)return;const d=(c.gdp/b.gdp-1)*100;$('#countryDetail').innerHTML=`<div class="country-detail-header"><div class="eyebrow">${c.code} / ECONOMY DETAIL</div><h2>${esc(c.name)}</h2><p>${time(quarter)} · Population baseline ${num(c.population)} · ${c.residual?'Residual aggregate':'Observed WDI baseline, modeled dynamics'}</p></div><div class="country-detail-grid">${kpi('Real GDP',money(c.gdp),sgn(d)+'% vs baseline','2023 USD',d<0)}${kpi('Inflation',pct(c.inflation),sgn(c.inflation-b.inflation)+' pp','Modeled annual rate',c.inflation>b.inflation)}${kpi('Unemployment',pct(c.unemployment),sgn(c.unemployment-b.unemployment)+' pp','Modeled labor share',c.unemployment>b.unemployment)}${kpi('Policy rate',pct(c.rate),sgn(c.rate-b.rate)+' pp','Assumed baseline + policy rule')}${kpi('FX index',c.fx.toFixed(1),sgn(c.fx-b.fx)+' index pts','Baseline = 100')}${kpi('Debt / GDP',pct(c.debt),sgn(c.debt-b.debt)+' pp','Assumed initial debt = 60%')}</div><div class="card"><div class="card-head"><h3>Observed starting trade exposure</h3></div><div class="method-body"><p>Exports: ${pct(obs.exports)} of GDP · Imports: ${pct(obs.imports)} of GDP.<br>These are WDI ratios. The network’s bilateral corridor weights are assumptions.</p></div></div><div class="detail-actions"><button id="focusCountry" class="primary">Focus this economy →</button><button id="targetCountry">Target shocks here</button><button id="inspectSources">Inspect data sources ↗</button></div><div id="sourceDetail"></div>`;$('#countryDialog').showModal();$('#focusCountry').onclick=()=>{selected=code;$('#countryDialog').close();changeView('overview');};$('#targetCountry').onclick=()=>{$('#target').value=code;dirty();$('#countryDialog').close();toast('Shock target set to '+c.name);};$('#inspectSources').onclick=()=>{$('#sourceDetail').innerHTML=`<div class="table-wrap" style="margin-top:20px"><table class="table"><thead><tr><th>Series</th><th>2023 observation</th><th>Indicator code</th></tr></thead><tbody>${Object.entries(obs.sources||{}).map(([k,s])=>`<tr><td>${esc(k)}</td><td>${s.value==null?'Missing (fallback used)':typeof s.value==='number'?s.value.toLocaleString('en',{maximumFractionDigits:3}):esc(s.value)}</td><td><a target="_blank" rel="noopener" href="https://api.worldbank.org/v2/country/${code}/indicator/${s.indicator}?date=2023&format=json">${s.indicator} ↗</a></td></tr>`).join('')}</tbody></table></div>`;};}
async function loadPreset(key){const preset=presets[key];if(!preset)return;const p={...DEFAULT,target:getParams().target,horizon:getParams().horizon,...preset.params};setParams(p);quarter=4;await execute(p);$$(`[data-preset="${key}"]`).forEach(b=>b.classList.add('active'));}
function persist(){try{localStorage.setItem('atlas-scenarios',JSON.stringify(saved));}catch{toast('Browser storage unavailable. Export the scenario JSON instead.');}}
function saveOpen(){$('#scenarioName').value='';$('#saveDialog').showModal();$('#scenarioName').focus();}
function download(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function exportResults(){appendLog('EXPORT','CSV / all countries / all computed quarters');const head=['quarter','period','country_code','country_name','gdp_billion_2023_usd','baseline_gdp_billion_2023_usd','output_impact_pct','annualized_growth_pct','inflation_pct','unemployment_pct','policy_rate_pct','fx_index','assumed_debt_gdp_pct','bank_risk_proxy','synthetic_intermediate_exports_billion_usd','io_relative_residual','shock_target',...inputs.map(k=>'shock_'+k)],rows=[head];run.frames.forEach((f,q)=>f.states.forEach(c=>{const b=base.frames[q].states.find(v=>v.code===c.code);rows.push([q,time(q),c.code,c.name,c.gdp,b.gdp,(c.gdp/b.gdp-1)*100,c.growth,c.inflation,c.unemployment,c.rate,c.fx,c.debt,c.risk,c.exportsValue,f.residual,run.params.target,...inputs.map(k=>run.params[k])]);}));const csv=rows.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\n');download('atlas-world-economy-results.csv',csv,'text/csv');toast('Quarterly results exported for all economies.');}
async function importScenario(e){try{const s=JSON.parse(await e.target.files[0].text());if(!s.name||!s.params)throw Error('Expected a named Atlas scenario');const p={...DEFAULT,...s.params};if(!model.countries.some(c=>c.code===p.target)&&p.target!=='ALL')throw Error('Unknown target');const bounds={fiscal:[0,1000],rate:[-3,5],tariff:[0,40],energy:[-40,100],supply:[0,40],carbon:[0,200],climate:[0,10],confidence:[-30,30]};for(const [k,[lo,hi]]of Object.entries(bounds))if(!Number.isFinite(p[k])||p[k]<lo||p[k]>hi)throw Error('Invalid '+k);if(![12,20,40].includes(p.horizon)||![1,4,8,20].includes(p.duration))throw Error('Invalid simulation horizon');saved.push({name:String(s.name).slice(0,60),params:p,createdAt:new Date().toISOString()});saved=saved.slice(-30);persist();render();toast('Scenario imported');}catch(e){toast('Import failed: '+e.message);}}
async function refreshData(){const b=$('#refreshData');b.disabled=true;$('#refreshStatus').textContent='Retrieving common-year 2023 observations…';try{const next=structuredClone(raw),codes=raw.countries.map(c=>c.code).concat('WLD').join(';'),series=Object.entries(raw.countries[0].sources),controller=new AbortController(),timer=setTimeout(()=>controller.abort(),25000);try{await Promise.all(series.map(async([k,s])=>{const res=await fetch(`https://api.worldbank.org/v2/country/${codes}/indicator/${s.indicator}?date=2023&format=json&per_page=100`,{signal:controller.signal});if(!res.ok)throw Error('World Bank API returned '+res.status);const [meta,rows]=await res.json();if(!Array.isArray(rows))throw Error('World Bank API response format changed');for(const row of rows){const c=row.countryiso3code==='WLD'?next.world:next.countries.find(c=>c.code===row.countryiso3code);if(c){c[k]=row.value;c.sources[k]={indicator:s.indicator,year:2023,value:row.value,updated:meta.lastupdated};}}}));}finally{clearTimeout(timer);}if(next.countries.some(c=>!c.gdp)||!next.world.gdp)throw Error('Required GDP data missing; baseline preserved');next.retrievedAt=new Date().toISOString().slice(0,10);raw=next;model=prepare(raw);await execute(run.params);toast('World Bank baseline refreshed for this session.');}catch(e){if($('#refreshStatus'))$('#refreshStatus').textContent='Refresh unavailable: '+e.message+'. The bundled baseline remains available.';b.disabled=false;}}

function appendLog(kind,message,q=null){
 const now=new Date();executionEvents.push({timestamp:now.toISOString(),time:now.toLocaleTimeString('en-GB',{hour12:false})+'.'+String(now.getMilliseconds()).padStart(3,'0'),run:runSequence,event:kind,quarter:q,message});
 if(executionEvents.length>500)executionEvents.shift();renderLedger();
}
function renderLedger(){
 const box=$('#executionLog');if(!box)return;const filter=$('#ledgerFilter').value;
 const events=executionEvents.filter(e=>filter==='ALL'||e.event===filter||(filter==='WARN'&&e.event==='ERROR'));
 $('#ledgerCount').textContent=executionEvents.length+' EVENTS';
 box.innerHTML=events.slice(-150).map(e=>`<div class="log-row"><time>${e.time}</time><span>R${String(e.run).padStart(4,'0')}</span><span class="log-level ${e.event==='WARN'||e.event==='ERROR'?'log-warn':e.event==='SOLVE'||e.event==='DONE'?'log-ok':''}">${esc(e.event)}</span><span>${esc(e.message)}</span></div>`).join('')||'<div class="empty-log">NO MATCHING EVENTS</div>';
 box.scrollTop=box.scrollHeight;
}
function logFrame(f){
 appendLog('SOLVE',`Q${String(f.quarter).padStart(2,'0')} GDP=${f.gdp.toFixed(3)}B  π=${f.inflation.toFixed(3)}%  u=${f.unemployment.toFixed(3)}%  r=${f.residual.toExponential(2)}  iter=${f.iterations}  ε=${f.accountingError.toExponential(2)}`,f.quarter);
 if(f.rationing<.999)appendLog('WARN',`Q${f.quarter} CAPACITY RATIONING ${(f.rationing*100).toFixed(2)}% of requested final demand`,f.quarter);
}
function stepQuarter(delta){if(!run)return;stop();quarter=Math.max(0,Math.min(run.params.horizon,quarter+delta));render();appendLog('STEP',`DISPLAY ${time(quarter)} · quarter step`,quarter);}
function simulationCanvas(){
 return `<div class="canvas-toolbar"><span>VISUALIZATION</span><div class="segmented">${[['map','GEOGRAPHY'],['network','TRADE NETWORK'],['flows','CAPITAL FLOWS']].map(([k,t])=>`<button data-canvas="${k}" class="${canvasMode===k?'active':''}">${t}</button>`).join('')}</div><span class="canvas-period">${time(quarter)}</span></div>`+(canvasMode==='flows'?`<div class="card"><div class="card-head"><h3>Capital propagation / input-output decomposition</h3><span class="badge">USD B</span></div>${sankey()}</div>`:mapCard(canvasMode==='network'));
}
function renderTelemetry(){
 const f=frames(),v=scope(f),b=scope(baseline());
 const dx=(a,k)=>a[k]-b[k];
 $('#deltaMetrics').innerHTML=`<div class="subhead metrics-scope">${selected?'ECONOMY '+selected:'GLOBAL AGGREGATE'} <span>VS NO-SHOCK RUN</span></div>`+cards()+`<div class="metric-ledger"><div><span>POLICY RATE</span><strong>${pct(v.rate,2)}</strong><em class="${dx(v,'rate')>0?'negative':'positive'}">${sgn(dx(v,'rate'))} pp</em></div><div><span>BANK RISK PROXY</span><strong>${pct(v.risk*100,2)}</strong><em class="${dx(v,'risk')>0?'negative':'positive'}">${sgn(dx(v,'risk')*100)} pp</em></div><div><span>INPUT EXPORTS</span><strong>${money(selected?v.exportsValue:f.trade)}</strong><em>MODELED</em></div></div>`;
 $('#quarterIndex').textContent=`Q${String(quarter).padStart(2,'0')} / Q${run.params.horizon}`;
 $('#solverStatus').textContent=f.residual<1e-10?'CONVERGED':'CHECK RESIDUAL';
 let maxCol=0;for(let j=0;j<model.N;j++)maxCol=Math.max(maxCol,1-model.va[j]);
 $('#solverDiagnostics').innerHTML=`<dl class="diagnostics"><div><dt>RELATIVE RESIDUAL</dt><dd class="positive">${f.residual.toExponential(3)}</dd></div><div><dt>ACCOUNTING ERROR</dt><dd class="positive">${f.accountingError.toExponential(3)}</dd></div><div><dt>ITERATIONS / MAX</dt><dd>${f.iterations} / 140</dd></div><div><dt>TOLERANCE</dt><dd>1.000e−10</dd></div><div><dt>MAX COLUMN Σ A</dt><dd>${maxCol.toFixed(6)}</dd></div><div><dt>DEMAND RATIONING</dt><dd class="${(f.rationing??1)<.999?'negative':''}">${((f.rationing??1)*100).toFixed(3)}%</dd></div><div><dt>LAST PAIRED RUN</dt><dd>${runTimeMs.toFixed(1)} ms</dd></div></dl>`;
 $('#phasePortrait').innerHTML=phaseChart();$('#canvasScope').textContent=selected||'GLOBAL';$('#terminalDimensions').textContent=`A[${model.N}×${model.N}] / ${model.countries.length} REGIONS / SEED ${run.seed}`;
}

async function init(){try{appendLog('BOOT','LOADING WDI 2023 SNAPSHOT / NATURAL EARTH GEOMETRY');$('#viewContent').innerHTML='<div class="loading"><span>◈</span>Assembling the world economy…</div>';[raw,geo]=await Promise.all(['baseline.json','world.json'].map(u=>fetch(u).then(r=>{if(!r.ok)throw Error('Missing '+u);return r.json();})));model=prepare(raw);$('#target').innerHTML='<option value="ALL">All economies · global shock</option>'+model.countries.map(c=>`<option value="${c.code}">${esc(c.name)}</option>`).join('');setParams(scenarioParams);runSequence=1;const started=performance.now();base=simulate(model,DEFAULT);run=simulate(model,scenarioParams,logFrame);runTimeMs=performance.now()-started;appendLog('DATA',`${model.countries.length} regions / ${model.N} nodes / ${run.agents.length} agents`);if(model.missing.length)appendLog('WARN',`${model.missing.length} missing series use disclosed fallbacks; see MODEL / DATA`);appendLog('DONE',`INITIAL PAIRED RUN COMPLETE / ${runTimeMs.toFixed(1)} ms`);$('#runStatus').textContent='CONVERGED';$('#coverage').textContent=`${model.countries.length} REGIONS / ${model.N} NODES / ${run.agents.length} AGENTS`;$('#timeline').max=run.params.horizon;$('#timelineEnd').textContent=time(run.params.horizon);const hash=location.hash.slice(1);if(titles[hash])view=hash;render();}catch(e){showError(e);$('#viewContent').innerHTML='<div class="empty-state">The baseline could not load. Please reload the page.</div>';}}
$$('#nav button').forEach(b=>b.onclick=()=>changeView(b.dataset.view));$('#countrySearch').oninput=countryList;$('#countryList').onclick=e=>{const b=e.target.closest('[data-country]');if(b)openCountry(b.dataset.country);};inputs.forEach(k=>{const range=$('#'+k),exact=$('#'+k+'Exact');range.oninput=()=>{exact.value=range.value;dirty();};exact.oninput=e=>{const v=+e.target.value;if(!Number.isFinite(v))return;range.value=Math.max(+range.min,Math.min(+range.max,v));dirty();};});['target','duration','horizon'].forEach(k=>$('#'+k).onchange=dirty);$$('.presets button').forEach(b=>b.onclick=()=>loadPreset(b.dataset.preset));$('#runBtn').onclick=()=>execute();$('#resetBtn').onclick=()=>{setParams({...DEFAULT,horizon:getParams().horizon});quarter=0;execute();};$('#saveBtn').onclick=saveOpen;$('#saveDialog').addEventListener('close',()=>{if($('#saveDialog').returnValue==='save'){const name=$('#scenarioName').value.trim();if(!name)return;const pending=JSON.stringify(getParams())!==JSON.stringify({...DEFAULT,...run.params});saved.push({name,params:{...run.params},createdAt:new Date().toISOString()});saved=saved.slice(-30);persist();if(view==='scenarios')render();toast(pending?'Saved the computed scenario. Run edited controls to save their changes.':'Scenario saved.');}});$('#countryDialog .dialog-close').onclick=()=>$('#countryDialog').close();$('#helpBtn').onclick=()=>changeView('model');$('#inspectMatrix').onclick=()=>{changeView('sectors');$('.matrix').scrollIntoView({block:'center'});appendLog('VIEW','INPUT-OUTPUT MATRIX / mean technical coefficients');};$('#exportBtn').onclick=exportResults;$('#playBtn').onclick=play;$('#timeline').oninput=e=>{stop();quarter=+e.target.value;render();appendLog('STEP',`DISPLAY ${time(quarter)} · manual seek`,quarter);};$('#prevTick').onclick=()=>stepQuarter(-1);$('#nextTick').onclick=()=>stepQuarter(1);$('#playSpeed').onchange=e=>{playDelay=+e.target.value;if(playing){stop();play();}};$('#ledgerFilter').onchange=renderLedger;$('#clearLog').onclick=()=>{executionEvents=[];renderLedger();};$('#exportLog').onclick=()=>download('atlas-execution-ledger.json',JSON.stringify(executionEvents,null,2),'application/json');init();
